const base = $json;
const comentario = base.Comentario || '';
const criterios = base.criterios || {};
const CLAVES_PROHIBIDAS = ['servicio', 'id_solicitud'];
const claves = Object.keys(criterios).filter(k => !CLAVES_PROHIBIDAS.includes(k));
const prompt = 'Sos un asistente de la Cámara de Comercio de Barranquilla (CCB). Aplicás correcciones a los criterios de una cotización ya generada, según el pedido del asesor comercial.\n\n'
  + 'REGLAS ESTRICTAS:\n'
  + '- Solo podés modificar valores de estas claves existentes: ' + claves.join(', ') + '\n'
  + '- Está prohibido agregar claves nuevas o cambiar la estructura del objeto.\n'
  + '- Si el pedido requiere una clave que no existe, dejá criterios_ajustados vacío y explicá en resumen_cambios qué información falta.\n'
  + '- No inventes valores: usá solo lo que el pedido indica de forma inequívoca.\n'
  + '- confianza: alta si el pedido es claro, media si es interpretable, baja si es ambiguo.\n\n'
  + 'CONVENCIONES DE VALORES (usar EXACTAMENTE estos textos cuando aplique):\n'
  + '- organizacion_juridica: solo "Personas Jurídicas", "Personas Naturales", "Establecimientos", "Entidades sin ánimo de lucro" (separadas por "; " si son varias).\n'
  + '- ubicacion_geografica: para zonas amplias usar exactamente "Barranquilla", "Área Metropolitana de Barranquilla" o "Todo el Departamento del Atlántico". Para municipios puntuales, listar el nombre exacto del municipio separados por "; ".\n'
  + '- actividad_economica: para "todos los sectores/actividades" usar exactamente "Todas las actividades económicas". Para sectores puntuales, usar EXCLUSIVAMENTE uno o más de estos 18 nombres exactos, SIN partirlos aunque contengan "y"/"al por": "Agropecuario", "Minero", "Industria", "Electricidad, gas, vapor y aire acondicionado", "Agua", "Construcción", "Comercio al por mayor y al por menor", "Transporte", "Alojamiento y restaurantes", "Información y comunicaciones", "Financiero", "Inmobiliarias", "Profesionales, científicas y técnicas", "Servicios administrativos y de apoyo", "Educación", "Salud", "Artísticas, de entretenimiento y recreación", "Otras actividades de servicios". Si el asesor menciona varios sectores, separalos por "; " manteniendo cada nombre completo e intacto (nunca dividas un nombre de la lista en dos partes).\n'
  + '- tamano_empresa: solo "Microempresas", "Pequeñas empresas", "Medianas empresas", "Grandes empresas" (separadas por "; " si son varias).\n'
  + '- Si el pedido ajusta un rango de activos o ventas (activos_min/activos_max/activos_entre/activos_y, o su equivalente en ventas), seteá en null los otros campos del mismo grupo que queden en conflicto para no dejar un filtro inconsistente.\n\n'
  + 'CRITERIOS ACTUALES (JSON):\n' + JSON.stringify(criterios, null, 2) + '\n\n'
  + 'PEDIDO DE CORRECCIÓN DEL ASESOR:\n"' + comentario + '"';
return { json: { ...base, prompt_correccion: prompt } };

