const base = $('Preparar corrección IA').first().json;
const raw = $json;
const out = (raw && typeof raw.output === 'object' && raw.output !== null) ? raw.output
  : (raw && typeof raw.response === 'object' && raw.response !== null) ? raw.response
  : (raw || {});
const ajustes = out.criterios_ajustados || {};
const criterios = { ...base.criterios };
const aplicadas = {};
const rechazadas = {};

// Valores permitidos por clave -- si la IA escribe algo fuera de esta lista para una clave
// controlada, se descarta el ajuste en vez de aplicarlo (evita corromper el criterio en
// silencio, p.ej. valores de organizacion_juridica escritos por error en tamano_empresa).
const VALORES_VALIDOS = {
  organizacion_juridica: ['Personas Jurídicas', 'Personas Naturales', 'Establecimientos', 'Entidades sin ánimo de lucro'],
  tamano_empresa: ['Microempresas', 'Pequeñas empresas', 'Medianas empresas', 'Grandes empresas'],
  actividad_economica: ['Agropecuario', 'Minero', 'Industria', 'Electricidad, gas, vapor y aire acondicionado', 'Agua', 'Construcción', 'Comercio al por mayor y al por menor', 'Transporte', 'Alojamiento y restaurantes', 'Información y comunicaciones', 'Financiero', 'Inmobiliarias', 'Profesionales, científicas y técnicas', 'Servicios administrativos y de apoyo', 'Educación', 'Salud', 'Artísticas, de entretenimiento y recreación', 'Otras actividades de servicios', 'Todas las actividades económicas']
};

function esValorValido(clave, valor) {
  const permitidos = VALORES_VALIDOS[clave];
  if (!permitidos) return true;
  const partes = String(valor).split(';').map(s => s.trim()).filter(Boolean);
  if (!partes.length) return false;
  return partes.every(p => permitidos.includes(p));
}

for (const [k, v] of Object.entries(ajustes)) {
  if (!Object.prototype.hasOwnProperty.call(criterios, k)) continue;
  if (esValorValido(k, v)) { criterios[k] = v; aplicadas[k] = v; }
  else { rechazadas[k] = v; }
}

const huboRechazos = Object.keys(rechazadas).length > 0;
const avisoRechazo = huboRechazos
  ? ' [AVISO: se descartaron ajustes invalidos para: ' + Object.keys(rechazadas).join(', ') + ' -- valor(es) no reconocido(s): ' + JSON.stringify(rechazadas) + ']'
  : '';

// F7-01: la confianza declarada por la IA viaja con el resultado para poder enrutar a revisión manual.
return { json: { id_solicitud: base.id_solicitud, servicio: base.servicio, criterios, criterios_ajustados_aplicados: aplicadas, criterios_ajustados_rechazados: rechazadas, resumen_cambios: (out.resumen_cambios || '') + avisoRechazo, comentario: base.Comentario || '', confianza: out.confianza || '',
  // F4-03: el aviso y el cierre corren en otros subflujos, asi que el contexto de la propuesta viaja en el item.
  contexto: { nombre_cliente: base.nombre_cliente || '', razon_social: base.razon_social || '',
              servicio: base.servicio || '', pdf_url: base.pdf_url || '',
              ronda_correccion: base.ronda_correccion, id_solicitud: base.id_solicitud,
              Comentario: base.Comentario || '' } } };

// F4-03: el cierre corre en otro subflujo, asi que el comentario del asesor y el contexto de la
// propuesta (que antes se leian de 'Consolidar datos y decision' dentro de W4-D) viajan en el item.
const get = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const ap = get('Aplicar correcciones');
const motor = $json || {};
return { json: { ...motor, Comentario: ap.comentario || motor.Comentario || '',
                 id_solicitud: motor.id_solicitud || ap.id_solicitud || '',
                 contexto: ap.contexto || {} } };

// F7-03: la respuesta de Teams no trae el contexto de la propuesta, asi que se vuelve a armar
// desde 'Aplicar correcciones' (ancestro) y se normaliza la aprobacion sea cual sea su forma.
const get = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const ap = get('Aplicar correcciones');
const r = $json || {};
const aprobado = (r.approved === true) || (r.aprobado === true) || (r.data && r.data.approved === true);
return { json: { ...ap, aprobado, aprobacion_cruda: r } };

